<?php

namespace App\Http\Middleware;

use Closure;
use Illuminate\Http\Request;
use Symfony\Component\HttpFoundation\Response;

class EnforceHttpsAndSecurityHeaders
{
    private const CONTENT_SECURITY_POLICY = "default-src 'self'; base-uri 'self'; object-src 'none'; frame-ancestors 'self'; form-action 'self'; script-src 'self' 'unsafe-inline' https://unpkg.com https://cdn.conferbot.com https://challenges.cloudflare.com https://maps.googleapis.com; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com https://maps.googleapis.com; font-src 'self' https://fonts.gstatic.com data:; img-src 'self' data: blob: https: http:; connect-src 'self' https://challenges.cloudflare.com https://maps.googleapis.com https://*.googleapis.com https://*.gstatic.com https://*.conferbot.com wss://*.conferbot.com; frame-src 'self' https://challenges.cloudflare.com https://*.google.com https://*.openstreetmap.org https://*.conferbot.com; worker-src 'self' blob:; upgrade-insecure-requests";

    /**
     * Handle an incoming request.
     *
     * @param  Closure(Request): (Response)  $next
     */
    public function handle(Request $request, Closure $next): Response
    {
        $isProduction = app()->isProduction();

        if ($isProduction && ! $request->isSecure()) {
            $secureBaseUrl = preg_replace('/^http:/i', 'https:', rtrim((string) config('app.url'), '/'));
            $securePath = '/'.ltrim($request->getPathInfo(), '/');
            $queryString = $request->getQueryString();

            if ($queryString !== null) {
                $securePath .= '?'.$queryString;
            }

            $response = redirect()->to($secureBaseUrl.$securePath, 301);
        } else {
            $response = $next($request);
        }

        if (! app()->isLocal()) {
            $response->headers->set('Content-Security-Policy', self::CONTENT_SECURITY_POLICY);
        }
        $response->headers->set('X-Frame-Options', 'SAMEORIGIN');
        $response->headers->set('X-Content-Type-Options', 'nosniff');
        $response->headers->set('Referrer-Policy', 'strict-origin-when-cross-origin');

        if ($isProduction && $request->isSecure()) {
            $response->headers->set('Strict-Transport-Security', 'max-age=31536000');
        }

        return $response;
    }
}
